var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 1720, VH = 860;
figDraw.viewbox(0, 0, VW, VH);

/* ── geometry constants (mirrors the source figure) ─────────────────────── */
var L_Y = [102, 230, 345, 475, 595];
var R_Y = [163, 288, 410, 535];
var NR = 30, SR = 27;
var EDGES = [[0, 0], [1, 0], [1, 2], [2, 1], [2, 2], [2, 3], [3, 2], [4, 2]];
var PANELS = { a: { lx: 62, rx: 305 }, b: { lx: 557, rx: 800 }, c: { lx: 1245, rx: 1490 } };
var S_POS = { x: 1058, y: 350 }, T_POS = { x: 1680, y: 350 };
var MATCH = { a: [[0, 0], [2, 2]], b: [[1, 0], [2, 1], [4, 2]] };
var FLOW_STATES = [[], [[0, 0]], [[0, 0], [2, 2]], [[1, 0], [2, 1], [4, 2]]];
var FLOW_LABEL = ['flow = empty  (|f| = 0)', 'flow = 1 unit  (|f| = 1)',
  'flow = 2 units  (|f| = 2)', 'flow = 3 units  (|f| = 3, maximum)'];

var SERIF = 'Georgia, "Times New Roman", serif';
var C_NODE = '#d9d9d9', C_OUT = '#1a1a1a', C_EDGE = '#000000';
var C_BAND = '#9e9e9e', C_SEL = '#f0932b', C_ACTIVE = '#1f6fb2';

var state = { panel: 'a', augment: 3, selected: null };
var Lb, Le, Ln, Lt, Lh;

/* ── small helpers ──────────────────────────────────────────────────────── */
function seg(ax, ay, bx, by, ra, rb) {
  var dx = bx - ax, dy = by - ay, d = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / d, uy = dy / d;
  return { x1: ax + ux * ra, y1: ay + uy * ra, x2: bx - ux * rb, y2: by - uy * rb, ux: ux, uy: uy };
}
function txt(g, x, y, s, size, italic, fill, halo) {
  var t = g.plain(s);
  t.font({ family: SERIF, size: size, style: italic ? 'italic' : 'normal' });
  t.attr({ x: x, y: y, 'text-anchor': 'middle', 'dominant-baseline': 'central', fill: fill || '#000' });
  if (halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}
function lp(pid, i) { return { x: PANELS[pid].lx, y: L_Y[i] }; }
function rp(pid, j) { return { x: PANELS[pid].rx, y: R_Y[j] }; }
function pkey(e) { return e[0] + '-' + e[1]; }

function drawBand(a, b, ra, rb, selected) {
  var s = seg(a.x, a.y, b.x, b.y, ra * 0.45, rb * 0.45);
  Lb.line(s.x1, s.y1, s.x2, s.y2)
    .stroke({ color: selected ? C_SEL : C_BAND, width: selected ? 19 : 15, linecap: 'round' });
}
function drawPlainEdge(a, b, ra, rb) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  Le.line(s.x1, s.y1, s.x2, s.y2).stroke({ color: C_EDGE, width: 2.2, linecap: 'round' });
}
function drawArrowEdge(a, b, ra, rb) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  var AH = 21, HW = 8.5;
  var bx = s.x2 - s.ux * AH, by = s.y2 - s.uy * AH;
  Le.line(s.x1, s.y1, bx, by).stroke({ color: C_EDGE, width: 2.2, linecap: 'round' });
  var px = -s.uy, py = s.ux;
  Le.polygon([[s.x2, s.y2], [bx + px * HW, by + py * HW], [bx - px * HW, by - py * HW]]).fill(C_EDGE);
}
function drawNode(pos, r, tip, popTitle, popBody) {
  var c = Ln.circle(r * 2).center(pos.x, pos.y).fill(C_NODE).stroke({ color: C_OUT, width: 3 });
  if (tip) {
    c.css('cursor', 'pointer');
    c.on('mousemove', function (ev) { showTooltip(tip, ev); });
    c.on('mouseleave', hideTooltip);
    if (popTitle) c.on('click', function () { showPopup(popTitle, popBody); });
  }
  return c;
}

/* ── clickable edge hit area ────────────────────────────────────────────── */
function addHit(a, b, ra, rb, pid, e, shaded) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  var k = pkey(e);
  var name = 'L' + (e[0] + 1) + ' – R' + (e[1] + 1);
  var h = Lh.line(s.x1, s.y1, s.x2, s.y2)
    .stroke({ color: '#fff', width: 26, opacity: 0, linecap: 'round' })
    .attr('pointer-events', 'stroke').css('cursor', 'pointer');
  h.on('mousemove', function (ev) {
    showTooltip(name + (shaded
      ? (pid === 'c' ? ' · carries 1 unit of flow (capacity 1)' : ' · in the matching')
      : ' · unused edge (capacity 1)'), ev);
  });
  h.on('mouseleave', hideTooltip);
  h.on('click', function () {
    if (shaded) {
      state.selected = (state.selected === k) ? null : k;
      figRender();
      if (state.selected) {
        showPopup('Matched pair ' + name,
          'In panel (c) this is the route s → L' + (e[0] + 1) + ' → R' + (e[1] + 1) + ' → t carrying one unit of flow. ' +
          'Because every edge has capacity 1, no other unit can reuse L' + (e[0] + 1) + ' or R' + (e[1] + 1) + '. ' +
          'That is exactly the rule that makes the shaded edges a matching: one unit of flow ⇔ one matched pair.');
      }
    } else {
      showPopup('Unused edge ' + name,
        'This edge carries no flow in the current solution. It could be used by a different matching, but only if both L' +
        (e[0] + 1) + ' and R' + (e[1] + 1) + ' are freed first — the unit capacities forbid sharing an endpoint. ' +
        'Press “Augment” to see the algorithm reroute flow to gain one more unit.');
    }
  });
}

/* ── panels ─────────────────────────────────────────────────────────────── */
function drawPanelAB(pid) {
  var P = PANELS[pid], M = MATCH[pid], i, j;
  var mset = {};
  for (i = 0; i < M.length; i++) mset[pkey(M[i])] = 1;
  for (i = 0; i < M.length; i++) {
    drawBand(lp(pid, M[i][0]), rp(pid, M[i][1]), NR, NR, state.selected === pkey(M[i]));
  }
  for (i = 0; i < EDGES.length; i++) {
    var e = EDGES[i];
    drawPlainEdge(lp(pid, e[0]), rp(pid, e[1]), NR, NR);
    addHit(lp(pid, e[0]), rp(pid, e[1]), NR, NR, pid, e, !!mset[pkey(e)]);
  }
  for (i = 0; i < 5; i++) {
    drawNode(lp(pid, i), NR, 'L' + (i + 1) + (mset['' + i + '-' + findMate(M, i)] ? '' : ''), null, null);
  }
  for (j = 0; j < 4; j++) drawNode(rp(pid, j), NR, 'R' + (j + 1), null, null);
  txt(Lt, P.lx, 690, 'L', 40, true, '#000');
  txt(Lt, P.rx, 690, 'R', 40, true, '#000');
  txt(Lt, (P.lx + P.rx) / 2, 782, '(' + pid + ')', 38, false,
    state.panel === pid ? C_ACTIVE : '#000');
}
function findMate(M, i) { for (var k = 0; k < M.length; k++) if (M[k][0] === i) return M[k][1]; return -1; }

function drawPanelC() {
  var P = PANELS.c, flow = FLOW_STATES[state.augment], i, j;
  var fset = {};
  for (i = 0; i < flow.length; i++) fset[pkey(flow[i])] = 1;

  /* highlight bands for whole s→L→R→t routes */
  for (i = 0; i < flow.length; i++) {
    var e = flow[i], sel = state.selected === pkey(e);
    var Lv = lp('c', e[0]), Rv = rp('c', e[1]);
    drawBand(S_POS, Lv, SR, NR, sel);
    drawBand(Lv, Rv, NR, NR, sel);
    drawBand(Rv, T_POS, NR, SR, sel);
  }
  /* arrows */
  for (i = 0; i < 5; i++) drawArrowEdge(S_POS, lp('c', i), SR, NR);
  for (i = 0; i < EDGES.length; i++) {
    var ed = EDGES[i];
    drawArrowEdge(lp('c', ed[0]), rp('c', ed[1]), NR, NR);
    addHit(lp('c', ed[0]), rp('c', ed[1]), NR, NR, 'c', ed, !!fset[pkey(ed)]);
  }
  for (j = 0; j < 4; j++) drawArrowEdge(rp('c', j), T_POS, NR, SR);

  /* nodes */
  for (i = 0; i < 5; i++) drawNode(lp('c', i), NR, 'L' + (i + 1) + ' · at most 1 unit may pass through', null, null);
  for (j = 0; j < 4; j++) drawNode(rp('c', j), NR, 'R' + (j + 1) + ' · at most 1 unit may pass through', null, null);
  drawNode(S_POS, SR, 'source s — one capacity-1 arc into every L vertex',
    'Source s', 'The source feeds one capacity-1 arc into each left vertex. That single unit of capacity is what prevents a left vertex from being matched twice.');
  drawNode(T_POS, SR, 'sink t — one capacity-1 arc out of every R vertex',
    'Sink t', 'Every right vertex sends one capacity-1 arc to the sink. The value of the flow reaching t is exactly the number of matched pairs.');
  txt(Lt, S_POS.x, S_POS.y, 's', 32, true, '#000');
  txt(Lt, T_POS.x, T_POS.y, 't', 32, true, '#000');

  txt(Lt, P.lx, 690, 'L', 40, true, '#000');
  txt(Lt, P.rx, 690, 'R', 40, true, '#000');
  txt(Lt, (S_POS.x + T_POS.x) / 2, 782, '(c)', 38, false, state.panel === 'c' ? C_ACTIVE : '#000');
}

/* ── counters + legend ──────────────────────────────────────────────────── */
function drawChrome() {
  var cx, label;
  if (state.panel === 'a') { cx = (PANELS.a.lx + PANELS.a.rx) / 2; label = '|M| = 2'; }
  else if (state.panel === 'b') { cx = (PANELS.b.lx + PANELS.b.rx) / 2; label = '|M| = 3  (maximum)'; }
  else {
    var n = FLOW_STATES[state.augment].length;
    cx = (S_POS.x + T_POS.x) / 2;
    label = '|f| = ' + n + (n === 3 ? '   =   |M| = 3' : '');
  }
  txt(Lt, cx, 40, label, 28, false, C_ACTIVE, true);

  Lt.line(62, 832, 122, 832).stroke({ color: C_BAND, width: 14, linecap: 'round' });
  var l1 = Lt.plain('= matching edge / unit of flow');
  l1.font({ family: SERIF, size: 22 }).attr({ x: 136, y: 832, 'dominant-baseline': 'central', fill: '#333' });
  var l2 = Lt.plain('every edge capacity = 1');
  l2.font({ family: SERIF, size: 22 }).attr({ x: 560, y: 832, 'dominant-baseline': 'central', fill: '#333' });
}

/* ── master render ──────────────────────────────────────────────────────── */
function figRender() {
  figDraw.clear();
  figDraw.rect(VW, VH).fill('#ffffff');
  Lb = figDraw.group(); Le = figDraw.group(); Ln = figDraw.group();
  Lt = figDraw.group(); Lh = figDraw.group();
  drawPanelAB('a');
  drawPanelAB('b');
  drawPanelC();
  drawChrome();
}

/* ── interactions ───────────────────────────────────────────────────────── */
function toggle_panelView(v) { state.panel = v; syncUI(); figRender(); }
function trigger_augmentStep() {
  state.augment = (state.augment + 1) % FLOW_STATES.length;
  var flow = FLOW_STATES[state.augment], ok = false, i;
  for (i = 0; i < flow.length; i++) if (pkey(flow[i]) === state.selected) ok = true;
  if (!ok && state.panel === 'c') state.selected = null;
  syncUI(); figRender();
  if (state.augment === 3) {
    showPopup('Augmenting to the maximum',
      'The third unit could not simply be added: the algorithm reroutes flow (L1→R1 becomes L2→R1, L3→R3 becomes L3→R2) so that L5→R3 becomes free. ' +
      'That is an augmenting path — the flow value rises from 2 to 3, and the matching grows from 2 pairs to 3 pairs, still vertex-disjoint.');
  }
}
function trigger_resetFlow() { state.augment = 0; state.selected = null; syncUI(); figRender(); }

/* ── demo steps ─────────────────────────────────────────────────────────── */
var demoSteps = [
  {
    title: 'A matching, but not a big one',
    narration: 'Panel (a) shows two shaded edges. No gray edge touches the same circle twice — that is what makes it a matching — but three circles on the left and two on the right are still unmatched.',
    st: { panel: 'a', augment: 3 }
  },
  {
    title: 'One more disjoint edge',
    narration: 'Panel (b) shades three edges instead of two, covering one extra vertex on each side. This is a maximum matching for this graph: no fourth edge can be added without reusing an endpoint.',
    st: { panel: 'b', augment: 3 }
  },
  {
    title: 'Turn the graph into a flow network',
    narration: 'Panel (c) adds a source s feeding every L vertex and a sink t fed by every R vertex, and orients all edges left to right. Every edge has capacity 1, so no vertex can carry more than one unit. The flow starts empty — press “Augment”.',
    st: { panel: 'c', augment: 0 }
  },
  {
    title: 'Three units of flow = three matched pairs',
    narration: 'Each shaded s→L→R→t path is vertex-disjoint from the others, and its middle arrow is precisely one of the shaded matching edges of panel (b). Maximum flow value 3 equals maximum matching size 3. Click a route to light it up in every panel.',
    st: { panel: 'c', augment: 3 }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(demoSteps.length - 1, i));
  var s = demoSteps[stepIdx];
  state.panel = s.st.panel;
  state.augment = s.st.augment;
  state.selected = null;
  syncUI();
  figRender();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

function syncUI() {
  var sel = document.getElementById('panelViewInput');
  if (sel) sel.value = state.panel;
  var a = document.getElementById('augmentState');
  if (a) a.textContent = FLOW_LABEL[state.augment];
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (stepIdx + 1) + ' / ' + demoSteps.length;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.innerHTML = '<b>' + demoSteps[stepIdx].title + '</b><br>' + demoSteps[stepIdx].narration;
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
