// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 1760, VH = 748;
figDraw.viewbox(0, 0, VW, VH);

/* ── geometry constants (mirrors the source figure) ─────────────────────── */
var L_Y = [55, 180, 300, 430, 548];
var R_Y = [115, 240, 362, 488];
var NR = 34, SR = 30;
var EDGES = [[0, 0], [1, 0], [1, 2], [2, 1], [2, 2], [2, 3], [3, 2], [4, 2]];
var PANELS = { a: { lx: 62, rx: 312 }, b: { lx: 560, rx: 810 }, c: { lx: 1215, rx: 1525 } };
var S_POS = { x: 1022, y: 350 }, T_POS = { x: 1702, y: 350 };
var MATCH = { a: [[0, 0], [2, 2]], b: [[1, 0], [2, 1], [4, 2]] };
var FLOW_STATES = [[], [[0, 0]], [[0, 0], [2, 2]], [[1, 0], [2, 1], [4, 2]]];
var FLOW_LABEL = ['panel (c) flow = empty  (|f| = 0)', 'panel (c) flow = 1 unit  (|f| = 1)',
  'panel (c) flow = 2 units  (|f| = 2)', 'panel (c) flow = 3 units  (|f| = 3, maximum)'];

var SERIF = 'Georgia, "Times New Roman", serif';
var C_NODE = '#d9d9d9', C_OUT = '#1a1a1a', C_EDGE = '#000000';
var C_BAND = '#b5b5b5', C_BAND_E = '#7a7a7a', C_SEL = '#f0932b', C_SEL_E = '#c9741a';

var state = { focus: 'all', augment: 3, selected: null };

/* ── small helpers ──────────────────────────────────────────────────────── */
function seg(ax, ay, bx, by, ra, rb) {
  var dx = bx - ax, dy = by - ay, d = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / d, uy = dy / d;
  return { x1: ax + ux * ra, y1: ay + uy * ra, x2: bx - ux * rb, y2: by - uy * rb, ux: ux, uy: uy };
}
function txt(g, x, y, s, size, italic, fill) {
  var t = g.plain(s);
  t.font({ family: SERIF, size: size, style: italic ? 'italic' : 'normal' });
  t.attr({ x: x, y: y, 'text-anchor': 'middle', 'dominant-baseline': 'central', fill: fill || '#000' });
  return t;
}
function lp(pid, i) { return { x: PANELS[pid].lx, y: L_Y[i] }; }
function rp(pid, j) { return { x: PANELS[pid].rx, y: R_Y[j] }; }
function pkey(e) { return e[0] + '-' + e[1]; }

/* gray ribbon: subtle darker border + lighter core; the thin black edge line
   is drawn afterwards by the edge layer, giving the dark centre line */
function drawBand(g, a, b, ra, rb, sel) {
  var s = seg(a.x, a.y, b.x, b.y, ra * 0.45, rb * 0.45);
  g.line(s.x1, s.y1, s.x2, s.y2)
    .stroke({ color: sel ? C_SEL_E : C_BAND_E, width: 25, linecap: 'round' });
  g.line(s.x1, s.y1, s.x2, s.y2)
    .stroke({ color: sel ? C_SEL : C_BAND, width: 19.5, linecap: 'round' });
}
function drawPlainEdge(g, a, b, ra, rb) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  g.line(s.x1, s.y1, s.x2, s.y2).stroke({ color: C_EDGE, width: 3, linecap: 'round' });
}
function drawArrowEdge(g, a, b, ra, rb) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  var AH = 24, HW = 10;
  var bx = s.x2 - s.ux * AH, by = s.y2 - s.uy * AH;
  g.line(s.x1, s.y1, bx, by).stroke({ color: C_EDGE, width: 3, linecap: 'round' });
  var px = -s.uy, py = s.ux;
  g.polygon([[s.x2, s.y2], [bx + px * HW, by + py * HW], [bx - px * HW, by - py * HW]]).fill(C_EDGE);
}
function drawNode(g, pos, r, tip, popTitle, popBody) {
  var c = g.circle(r * 2).center(pos.x, pos.y).fill(C_NODE).stroke({ color: C_OUT, width: 3.5 });
  if (tip) {
    c.css('cursor', 'pointer');
    c.on('mousemove', function (ev) { showTooltip(tip, ev); });
    c.on('mouseleave', hideTooltip);
    if (popTitle) c.on('click', function () { showPopup(popTitle, popBody); });
  }
  return c;
}

/* ── clickable edge hit area ────────────────────────────────────────────── */
function addHit(g, a, b, ra, rb, pid, e, shaded) {
  var s = seg(a.x, a.y, b.x, b.y, ra, rb);
  var k = pkey(e);
  var name = 'L' + (e[0] + 1) + ' – R' + (e[1] + 1);
  var h = g.line(s.x1, s.y1, s.x2, s.y2)
    .stroke({ color: '#fff', width: 28, opacity: 0, linecap: 'round' })
    .attr('pointer-events', 'stroke').css('cursor', 'pointer');
  h.on('mousemove', function (ev) {
    showTooltip(name + (shaded
      ? (pid === 'c' ? ' · carries 1 unit of flow (capacity 1)' : ' · in the matching')
      : ' · unused edge (capacity 1)'), ev);
  });
  h.on('mouseleave', hideTooltip);
  h.on('click', function () {
    if (shaded) {
      state.selected = (state.selected === k) ? null : k;
      figRender();
      if (state.selected) {
        showPopup('Matched pair ' + name,
          'In panel (c) this is the route s → L' + (e[0] + 1) + ' → R' + (e[1] + 1) + ' → t carrying one unit of flow. ' +
          'Because every edge has capacity 1, no other unit can reuse L' + (e[0] + 1) + ' or R' + (e[1] + 1) + '. ' +
          'That is exactly the rule that makes the shaded edges a matching: one unit of flow ⇔ one matched pair.');
      }
    } else {
      showPopup('Unused edge ' + name,
        'This edge carries no flow in the current solution. It could belong to a different matching, but only if both L' +
        (e[0] + 1) + ' and R' + (e[1] + 1) + ' are freed first — the unit capacities forbid sharing an endpoint. ' +
        'Press “Augment” to watch the algorithm reroute flow and gain one more unit.');
    }
  });
}

/* ── panels ─────────────────────────────────────────────────────────────── */
function drawPanelAB(pid, g) {
  var P = PANELS[pid], M = MATCH[pid], i, j;
  var gb = g.group(), ge = g.group(), gn = g.group(), gt = g.group(), gh = g.group();
  var mset = {};
  for (i = 0; i < M.length; i++) mset[pkey(M[i])] = 1;
  for (i = 0; i < M.length; i++) {
    drawBand(gb, lp(pid, M[i][0]), rp(pid, M[i][1]), NR, NR, state.selected === pkey(M[i]));
  }
  for (i = 0; i < EDGES.length; i++) {
    var e = EDGES[i];
    drawPlainEdge(ge, lp(pid, e[0]), rp(pid, e[1]), NR, NR);
    addHit(gh, lp(pid, e[0]), rp(pid, e[1]), NR, NR, pid, e, !!mset[pkey(e)]);
  }
  for (i = 0; i < 5; i++) drawNode(gn, lp(pid, i), NR, 'L' + (i + 1), null, null);
  for (j = 0; j < 4; j++) drawNode(gn, rp(pid, j), NR, 'R' + (j + 1), null, null);
  txt(gt, P.lx, 634, 'L', 50, true, '#000');
  txt(gt, P.rx, 634, 'R', 50, true, '#000');
  txt(gt, (P.lx + P.rx) / 2, 712, '(' + pid + ')', 50, false, '#000');
}

function drawPanelC(g) {
  var P = PANELS.c, flow = FLOW_STATES[state.augment], i, j;
  var gb = g.group(), ge = g.group(), gn = g.group(), gt = g.group(), gh = g.group();
  var fset = {};
  for (i = 0; i < flow.length; i++) fset[pkey(flow[i])] = 1;

  /* gray ribbons tracing whole s→L→R→t routes */
  for (i = 0; i < flow.length; i++) {
    var e = flow[i], sel = state.selected === pkey(e);
    var Lv = lp('c', e[0]), Rv = rp('c', e[1]);
    drawBand(gb, S_POS, Lv, SR, NR, sel);
    drawBand(gb, Lv, Rv, NR, NR, sel);
    drawBand(gb, Rv, T_POS, NR, SR, sel);
  }
  for (i = 0; i < 5; i++) drawArrowEdge(ge, S_POS, lp('c', i), SR, NR);
  for (i = 0; i < EDGES.length; i++) {
    var ed = EDGES[i];
    drawArrowEdge(ge, lp('c', ed[0]), rp('c', ed[1]), NR, NR);
    addHit(gh, lp('c', ed[0]), rp('c', ed[1]), NR, NR, 'c', ed, !!fset[pkey(ed)]);
  }
  for (j = 0; j < 4; j++) drawArrowEdge(ge, rp('c', j), T_POS, NR, SR);

  for (i = 0; i < 5; i++) drawNode(gn, lp('c', i), NR, 'L' + (i + 1) + ' · at most 1 unit may pass through', null, null);
  for (j = 0; j < 4; j++) drawNode(gn, rp('c', j), NR, 'R' + (j + 1) + ' · at most 1 unit may pass through', null, null);
  drawNode(gn, S_POS, SR, 'source s — one capacity-1 arc into every L vertex',
    'Source s', 'The source feeds one capacity-1 arc into each left vertex. That single unit of capacity is what prevents a left vertex from being matched twice.');
  drawNode(gn, T_POS, SR, 'sink t — one capacity-1 arc out of every R vertex',
    'Sink t', 'Every right vertex sends one capacity-1 arc to the sink. The value of the flow arriving at t is exactly the number of matched pairs.');
  txt(gt, S_POS.x, S_POS.y, 's', 42, true, '#000');
  txt(gt, T_POS.x, T_POS.y, 't', 42, true, '#000');

  txt(gt, P.lx, 634, 'L', 50, true, '#000');
  txt(gt, P.rx, 634, 'R', 50, true, '#000');
  txt(gt, (P.lx + P.rx) / 2, 712, '(c)', 50, false, '#000');
}

/* ── master render ──────────────────────────────────────────────────────── */
function figRender() {
  figDraw.clear();
  figDraw.rect(VW, VH).fill('#ffffff');
  var gA = figDraw.group(), gB = figDraw.group(), gC = figDraw.group();
  drawPanelAB('a', gA);
  drawPanelAB('b', gB);
  drawPanelC(gC);
  var f = state.focus;
  gA.opacity(f === 'all' || f === 'a' ? 1 : 0.16);
  gB.opacity(f === 'all' || f === 'b' ? 1 : 0.16);
  gC.opacity(f === 'all' || f === 'c' ? 1 : 0.16);
}

/* ── interactions ───────────────────────────────────────────────────────── */
function toggle_panelView(v) { state.focus = v; syncUI(); figRender(); }
function trigger_augmentStep() {
  state.augment = (state.augment + 1) % FLOW_STATES.length;
  var flow = FLOW_STATES[state.augment], ok = false, i;
  for (i = 0; i < flow.length; i++) if (pkey(flow[i]) === state.selected) ok = true;
  if (!ok && state.focus === 'c') state.selected = null;
  syncUI(); figRender();
  if (state.augment === 3) {
    showPopup('Augmenting to the maximum',
      'The third unit could not simply be added: the algorithm reroutes flow (L1→R1 becomes L2→R1, L3→R3 becomes L3→R2) so that L5→R3 becomes free. ' +
      'That is an augmenting path — the flow value rises from 2 to 3, and the matching grows from 2 pairs to 3 pairs, still vertex-disjoint.');
  }
}
function trigger_resetFlow() { state.augment = 0; state.selected = null; syncUI(); figRender(); }

/* ── demo steps ─────────────────────────────────────────────────────────── */
var demoSteps = [
  {
    title: 'A matching, but not a big one',
    narration: 'The full figure. In panel (a) two edges carry a thick gray ribbon: no ribbon touches the same circle twice — that is what makes it a matching — but three circles on the left and two on the right stay unmatched.',
    st: { focus: 'all', augment: 3 }
  },
  {
    title: 'One more disjoint edge',
    narration: 'Focus on panel (b): three shaded edges instead of two, covering one extra vertex on each side. This is a maximum matching for this graph — no fourth edge can be added without reusing an endpoint.',
    st: { focus: 'b', augment: 3 }
  },
  {
    title: 'Turn the graph into a flow network',
    narration: 'Panel (c) adds a source s feeding every L vertex and a sink t fed by every R vertex, and orients all edges left to right. Every edge has capacity 1, so no vertex can carry more than one unit. The flow starts empty — press “Augment”.',
    st: { focus: 'c', augment: 0 }
  },
  {
    title: 'Three units of flow = three matched pairs',
    narration: 'Each shaded s→L→R→t route is vertex-disjoint from the others, and its middle arrow is precisely one of the shaded matching edges of panel (b). Maximum flow value 3 equals maximum matching size 3. Click a route to light it up in every panel.',
    st: { focus: 'c', augment: 3 }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(demoSteps.length - 1, i));
  var s = demoSteps[stepIdx];
  state.focus = s.st.focus;
  state.augment = s.st.augment;
  state.selected = null;
  syncUI();
  figRender();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

function syncUI() {
  var sel = document.getElementById('panelViewInput');
  if (sel) sel.value = state.focus;
  var a = document.getElementById('augmentState');
  if (a) a.textContent = FLOW_LABEL[state.augment];
  var fv = document.getElementById('flowVal');
  if (fv) fv.textContent = String(FLOW_STATES[state.augment].length);
  var fe = document.getElementById('flowEq');
  if (fe) fe.style.display = (state.augment === 3) ? '' : 'none';
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (stepIdx + 1) + ' / ' + demoSteps.length;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.innerHTML = '<b>' + demoSteps[stepIdx].title + '</b><br>' + demoSteps[stepIdx].narration;
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

